const galleryImages = [
  { src: media('factory-assembly.png'), alt: '消防设备装配场景', caption: '设备装配 · 生产现场' },
  { src: media('engineer-service.png'), alt: '技术人员巡检场景', caption: '技术巡检 · 服务现场' },
  { src: media('application-server-room.png'), alt: '服务器机房场景', caption: '数据中心 · 应用领域' },
  { src: media('product-cylinder-bank.png'), alt: '气体灭火瓶组设备', caption: '瓶组设备 · 产品资料' }
]
let heroTimer
const nextHero = () => { activeHeroIndex.value = (activeHeroIndex.value + 1) % heroSlides.length }
const previousHero = () => { activeHeroIndex.value = (activeHeroIndex.value + heroSlides.length - 1) % heroSlides.length }
const startHeroTimer = () => { clearInterval(heroTimer); if (!heroPaused.value && !heroHover.value && !heroFocus.value) heroTimer = window.setInterval(nextHero, 6500) }
const pauseHeroForPointer = () => { heroHover.value = true; clearInterval(heroTimer) }
const resumeHeroForPointer = () => { heroHover.value = false; startHeroTimer() }
const pauseHeroForFocus = () => { heroFocus.value = true; clearInterval(heroTimer) }
const resumeHeroForFocus = (event) => { if (!event.currentTarget.contains(event.relatedTarget)) { heroFocus.value = false; startHeroTimer() } }
const toggleHeroTimer = () => { heroPaused.value = !heroPaused.value; startHeroTimer() }
const openProduct = (product) => { selectedProduct.value = product }
const submitInquiry = async () => {
  if (inquiryLoading.value || inquirySubmitted.value) return
  inquiryError.value = ''
  inquiryLoading.value = true
  try {
    const lead = await submitHuizhongInquiry(inquiryForm.value)
    inquiryReference.value = lead.publicRef
    inquirySubmitted.value = true
  } catch (error) {
    inquiryError.value = error instanceof Error ? error.message : '需求提交失败，请稍后重试。'
  } finally {
    inquiryLoading.value = false
  }
}
const openLogin = async () => {
  mobileOpen.value = false
  loginError.value = ''
  loginOpen.value = true
  await nextTick()
  document.querySelector('#huizhong-login-username')?.focus()
}
const closeLogin = () => {
  if (loginLoading.value) return
  loginOpen.value = false
  loginError.value = ''
  loginForm.value.password = ''
}
const submitLogin = async () => {
  if (loginLoading.value) return
  loginError.value = ''
  loginLoading.value = true
  try {
    await authenticateHuizhong(loginForm.value)
    window.location.assign(eiscoreEntryPath)
  } catch (error) {
    loginError.value = error instanceof Error ? error.message : '登录失败，请稍后重试。'
  } finally {
    loginLoading.value = false
  }
}
const onScroll = () => { scrolled.value = window.scrollY > 30 }
const onKeydown = (event) => { if (event.key === 'Escape') { selectedProduct.value = null; inquiryOpen.value = false; closeLogin() } }
onMounted(() => {
  window.addEventListener('scroll', onScroll, { passive: true })
  window.addEventListener('keydown', onKeydown)
  startHeroTimer()
})
onBeforeUnmount(() => { window.removeEventListener('scroll', onScroll); window.removeEventListener('keydown', onKeydown); clearInterval(heroTimer) })
</script>

